<?php require __DIR__.'/inc/header.php';$title='Coupons';$pdo=db();if(is_post()){verify_csrf();$pdo->prepare('INSERT OR REPLACE INTO coupons(code,type,value,min_amount,max_discount,usage_limit) VALUES(?,?,?,?,?,?)')->execute([strtoupper(trim((string)post('code'))),(string)post('type'),(float)post('value'),(float)post('min_amount',0),post('max_discount')!==''?(float)post('max_discount'):null,post('usage_limit')!==''?(int)post('usage_limit'):null]);flash('success','Coupon saved.');redirect('/admin/coupons.php');}$rows=$pdo->query('SELECT * FROM coupons ORDER BY id DESC')->fetchAll();?><div class="mb-6"><div class="text-xs tracking-[.2em] text-slate-400 font-black">MARKETING</div><h1 class="text-3xl font-black">Coupons</h1></div><div class="grid lg:grid-cols-[380px_1fr] gap-6"><form method="post" class="bg-white border rounded-2xl p-5"><?=csrf_input()?><div class="font-black">Create Coupon</div><input name="code" required placeholder="WELCOME10" class="w-full mt-4 rounded-xl border-slate-200"><select name="type" class="w-full mt-3 rounded-xl border-slate-200"><option value="percent">Percent</option><option value="fixed">Fixed</option></select><div class="grid grid-cols-2 gap-2 mt-3"><input type="number" step="0.01" name="value" placeholder="Value" class="rounded-xl border-slate-200"><input type="number" step="0.01" name="min_amount" placeholder="Min amount" class="rounded-xl border-slate-200"></div><input type="number" step="0.01" name="max_discount" placeholder="Max discount" class="w-full mt-3 rounded-xl border-slate-200"><input type="number" name="usage_limit" placeholder="Usage limit" class="w-full mt-3 rounded-xl border-slate-200"><button class="w-full mt-4 py-3 rounded-xl bg-slate-950 text-white font-black">Save Coupon</button></form><div class="bg-white border rounded-2xl overflow-hidden"><table class="w-full text-sm"><thead class="bg-slate-50"><tr><th class="p-3 text-left">Code</th><th class="p-3">Type</th><th class="p-3">Value</th><th class="p-3">Used</th></tr></thead><tbody><?php foreach($rows as $r):?><tr class="border-t"><td class="p-3 font-black"><?=e($r['code'])?></td><td class="p-3 text-center"><?=e($r['type'])?></td><td class="p-3 text-center"><?=e($r['value'])?></td><td class="p-3 text-center"><?=$r['used_count']?></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/inc/footer.php';?>
